use std::{collections::HashMap,time::Instant};
use serde_json::{json,Value};
type B=Vec<u32>;
#[derive(Default)]struct A{nodes:Vec<[u32;3]>,memo:HashMap<(u32,u32,u32),u32>,inputs:usize,cutoff:usize}
impl A{fn new()->Self{Self{nodes:vec![[0,0,0],[0,1,0]],..Self::default()}}fn input(&mut self)->u32{let id=self.nodes.len()as u32;self.nodes.push([1,self.inputs as u32,0]);self.inputs+=1;id}fn gate(&mut self,op:u32,mut x:u32,mut y:u32)->u32{if x>y{std::mem::swap(&mut x,&mut y);}if op==2{if x==0{return y;}if x==y{return 0;}}else{if x==0{return 0;}if x==1||x==y{return y;}}if let Some(id)=self.memo.get(&(op,x,y)){return *id;}let id=self.nodes.len()as u32;self.nodes.push([op,x,y]);self.memo.insert((op,x,y),id);id}fn xor(&mut self,x:u32,y:u32)->u32{self.gate(2,x,y)}fn and(&mut self,x:u32,y:u32)->u32{self.gate(3,x,y)}fn eval(&self,inputs:&[bool],eq:&[u32])->bool{assert_eq!(inputs.len(),self.inputs);let mut v=vec![false;self.nodes.len()];v[1]=true;for(i,n)in self.nodes.iter().enumerate().skip(2){v[i]=match n[0]{1=>inputs[n[1]as usize],2=>v[n[1]as usize]^v[n[2]as usize],3=>v[n[1]as usize]&v[n[2]as usize],_=>panic!()};}eq.iter().all(|i|!v[*i as usize])}fn summary(&self,eq:&[u32])->Value{let and=self.nodes.iter().filter(|x|x[0]==3).count();let xor=self.nodes.iter().filter(|x|x[0]==2).count();let units=eq.iter().filter(|x|**x!=0).count();json!({"inputs":self.inputs,"and_gates":and,"xor_gates":xor,"zero_constraints":units,"tseitin_clauses":3*and+4*xor+units,"total_nodes":self.nodes.len()})}}
fn trim(mut x:B)->B{while x.last()==Some(&0){x.pop();}x}
fn add(a:&mut A,x:&B,y:&B)->B{let mut z=vec![0;x.len().max(y.len())];for(i,t)in z.iter_mut().enumerate(){*t=a.xor(*x.get(i).unwrap_or(&0),*y.get(i).unwrap_or(&0));}trim(z)}
fn school(a:&mut A,x:&B,y:&B)->B{if x.is_empty()||y.is_empty(){return vec![];}let mut z=vec![0;x.len()+y.len()-1];for(i,x)in x.iter().enumerate(){for(j,y)in y.iter().enumerate(){let p=a.and(*x,*y);z[i+j]=a.xor(z[i+j],p);}}trim(z)}
fn shifted(x:&B,n:usize)->B{if x.is_empty(){return vec![];}let mut out=vec![0;n];out.extend(x);out}
fn mul(a:&mut A,x:&B,y:&B)->B{if x.is_empty()||y.is_empty(){return vec![];}let small=x.len().min(y.len());let big=x.len().max(y.len());if a.cutoff==0||big<=a.cutoff||small<=2{return school(a,x,y);}if big>2*small{let(short,long)=if x.len()<y.len(){(x,y)}else{(y,x)};let mut out=vec![];for(i,part)in long.chunks(small).enumerate(){let p=mul(a,short,&part.to_vec());out=add(a,&out,&shifted(&p,i*small));}return out;}let m=big.div_ceil(2);let x0=x[..m.min(x.len())].to_vec();let x1=x[m.min(x.len())..].to_vec();let y0=y[..m.min(y.len())].to_vec();let y1=y[m.min(y.len())..].to_vec();let z0=mul(a,&x0,&y0);let z2=mul(a,&x1,&y1);let sx=add(a,&x0,&x1);let sy=add(a,&y0,&y1);let mid=mul(a,&sx,&sy);let mid=add(a,&mid,&z0);let mid=add(a,&mid,&z2);let out=add(a,&z0,&shifted(&mid,m));add(a,&out,&shifted(&z2,2*m))}

fn rem(a:&mut A,x:&B,m:u64)->B{let d=63-m.leading_zeros()as usize;let mut z=x.clone();for i in (d..z.len()).rev(){let t=z[i];if t==0{continue;}z[i]=0;for j in 0..d{if m>>j&1!=0{z[i-d+j]=a.xor(z[i-d+j],t);}}}z.truncate(d);trim(z)}
fn prem(mut x:u64,m:u64)->u64{while x!=0&&x.ilog2()>=m.ilog2(){x^=m<<(x.ilog2()-m.ilog2());}x}
fn gcd(mut x:u64,mut y:u64)->u64{while y!=0{let r=prem(x,y);x=y;y=r;}x}
fn irreduc(m:u64)->bool{let d=m.ilog2();for k in 1..=d/2{for q in (1<<k)..(1<<(k+1)){if prem(m,q)==0{return false;}}}true}
fn moduli(need:usize)->Vec<u64>{let mut out=vec![];let mut degree=0;for m in [16,17,21,19,25,31]{out.push(m);degree+=4;if degree>=need{return out;}}for d in [3,5,6,7,8,9,10,11,12]{for m in (1u64<<d)..(1u64<<(d+1)){if irreduc(m){assert!(out.iter().all(|x|gcd(*x,m)==1));out.push(m);degree+=d;if degree>=need{return out;}}}}panic!("CRT degree cap")}
fn build(n:usize,d:usize,f:&[usize],mods:Option<&[u64]>,cutoff:usize)->(A,Vec<u32>){assert!(4*(d-1)<n);let mut a=A::new();a.cutoff=cutoff;let roots=(0..5).map(|_|(0..d).map(|_|a.input()).collect::<B>()).collect::<Vec<_>>();let mut rhs=(0..5).map(|_|(0..n).map(|_|a.input()).collect::<B>()).collect::<Vec<_>>();let qbits=(5*(d-1)+1).saturating_sub(n);let q=(0..qbits).map(|_|a.input()).collect::<Vec<_>>();for(i,q)in q.iter().enumerate(){rhs[0].resize(n+qbits,0);for j in f{let t=i+j;rhs[0][t]=a.xor(rhs[0][t],*q);}}
 let places=mods.map(|m|m.iter().copied().map(Some).collect::<Vec<_>>()).unwrap_or(vec![None]);let mut eq=vec![];
 for place in places{let mut p=vec![vec![1]];for root in &roots{let r=if let Some(m)=place{rem(&mut a,root,m)}else{root.clone()};let mut out=vec![vec![];p.len()+1];for(j,c)in p.iter().enumerate(){let product=mul(&mut a,c,&r);let product=if let Some(m)=place{rem(&mut a,&product,m)}else{product};out[j]=add(&mut a,&out[j],&product);out[j+1]=add(&mut a,&out[j+1],c);}p=out;}for j in 0..5{let h=if let Some(m)=place{rem(&mut a,&rhs[j],m)}else{rhs[j].clone()};eq.extend(add(&mut a,&p[j],&h));}}
 (a,eq)}
fn pmul(mut x:u64,mut y:u64)->u64{let mut z=0;while y!=0{if y&1!=0{z^=x;}x<<=1;y>>=1;}z}
fn base_controls()->Value{let mods=moduli(6);let(a,eq)=build(5,2,&[0,2,5],None,0);let(b,beq)=build(5,2,&[0,2,5],Some(&mods),16);let mut checks=0;for mask in 0u64..1024{let roots=(0..5).map(|i|(mask>>(2*i))&3).collect::<Vec<_>>();let mut p=vec![1u64];for r in roots{let mut next=vec![0;p.len()+1];for(j,c)in p.iter().enumerate(){next[j]^=pmul(*c,r);next[j+1]^=c;}p=next;}let canonical=p[..5].iter().map(|x|prem(*x,37)).collect::<Vec<_>>();let q=(p[0]^canonical[0])>>5;assert!(q<=1);let mut bits=(0..10).map(|i|mask>>i&1!=0).collect::<Vec<_>>();for c in &canonical{bits.extend((0..5).map(|i|c>>i&1!=0));}bits.push(q!=0);assert!(a.eval(&bits,&eq)&&b.eval(&bits,&beq));checks+=1;for j in 10..bits.len(){bits[j]^=true;assert!(!a.eval(&bits,&eq)&&!b.eval(&bits,&beq));bits[j]^=true;checks+=1;}}
 let(c,ceq)=build(5,2,&[0,2,5],Some(&[16]),8);let mut bad=vec![false;a.inputs];bad[10+4*5+4]=true;assert!(!a.eval(&bad,&eq));assert!(c.eval(&bad,&ceq));json!({"status":"passed","independent_literal_coefficient_cases":checks,"insufficient_CRT_degree_counterexample":true,"oracle":"literal carryless polynomial products, correct assignments and every single RHS-bit mutation"})}
fn controls()->Value{let mut result=base_controls();let mut count=0;let mut rng=2026101771u64;for(nx,ny)in [(18,18),(35,18),(52,18),(69,18),(140,140),(557,140)]{for cutoff in [8,16,32]{let mut a=A::new();a.cutoff=cutoff;let x=(0..nx).map(|_|a.input()).collect::<B>();let y=(0..ny).map(|_|a.input()).collect::<B>();let out=mul(&mut a,&x,&y);for _ in 0..16{let input=(0..nx+ny).map(|_|{rng^=rng<<13;rng^=rng>>7;rng^=rng<<17;rng&1!=0}).collect::<Vec<_>>();let mut want=vec![false;nx+ny-1];for i in 0..nx{for j in 0..ny{want[i+j]^=input[i]&input[nx+j];}}let mut v=vec![false;a.nodes.len()];v[1]=true;for(i,node)in a.nodes.iter().enumerate().skip(2){v[i]=match node[0]{1=>input[node[1]as usize],2=>v[node[1]as usize]^v[node[2]as usize],3=>v[node[1]as usize]&v[node[2]as usize],_=>panic!()};}for(i,w)in want.iter().enumerate(){assert_eq!(*w,out.get(i).is_some_and(|wire|v[*wire as usize]));}count+=1;}}}result["independent_adaptive_multiplication_vectors"]=json!(count);result}

fn run(id:&str)->Value{let start=Instant::now();let mut rows=vec![];for(n,d,f)in [(83,18,vec![0,1,2,45,83]),(163,40,vec![0,3,6,7,163]),(233,56,vec![0,74,233]),(283,70,vec![0,5,7,12,283]),(409,100,vec![0,87,409]),(571,140,vec![0,2,5,10,571])]{let mut variants=vec![];for cutoff in [0,8,16,32]{let t=Instant::now();let(a,eq)=build(n,d,&f,None,cutoff);variants.push(json!({"cutoff":cutoff,"counts":a.summary(&eq),"compile_seconds_diagnostic":t.elapsed().as_secs_f64()}));}rows.push(json!({"field_degree":n,"source_dimension":d,"variants":variants,"profile_complete":true}));assert!(start.elapsed().as_secs()<65);}json!({"schema":"scientific_result_v1","experiment_id":id,"status":"passed","summary":"Adaptive direct source-product multiplication compared with specialized schoolbook circuits across six binary widths.","evidence":{"rows":rows,"scope":"source-product/equality subsystem only; norm generation and all-root solving omitted","original_root_count_exact":null,"release_gate_claim":false,"novelty_claim":false},"next_actions":["Keep every cutoff and width result. Refuse blanket promotion if no fixed preregistered cutoff meets both AND and clause thresholds.","Use any deterministic component improvement only after exact original-equivalent end-to-end solver comparison.","Retain odd-prime interval integration and complete matched F4/F5/F6 baselines."]})}

fn main(){let a:Vec<_>=std::env::args().collect();if a.get(1).is_some_and(|x|x=="controls"){println!("{}",controls());return;}let t=Instant::now();let mut r=run(a.get(1).expect("id"));let mut s=r.to_string();if t.elapsed().as_secs()>=70{r["status"]=json!("inconclusive");if let Some(rows)=r["evidence"]["rows"].as_array_mut(){for row in rows{row["profile_complete"]=json!(false);}}s=r.to_string();}println!("{s}");}
